const $=id=>document.getElementById(id),{run,qa,scenarios,names}=Nexo;
let current=0,last=null;
const fmt=v=>v===null?'No definido':!Number.isFinite(v)?'Fuera de rango':v!==0&&(Math.abs(v)<.001||Math.abs(v)>=1e5)?v.toExponential(5):v.toLocaleString('es-BO',{maximumFractionDigits:6}),vec=v=>'['+v.map(fmt).join('; ')+']',money=v=>v.toLocaleString('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2});
function table(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function matrixText(A){return A.map(r=>r.map(v=>fmt(v).padStart(14)).join('')).join('\n');}
function load(i){current=i;const s=scenarios[i];$('scenarioButtons').innerHTML=scenarios.map((s,j)=>`<button class="${j===i?'selected':''}" data-scenario="${j}">${['01','02','03'][j]} &nbsp; ${s.name}</button>`).join('');$('scenarioNote').textContent=s.note; $('matrix').innerHTML=s.A.map((r,i)=>r.map((v,j)=>`<input type="number" step="any" value="${v}" data-i="${i}" data-j="${j}" aria-label="A fila ${i+1} columna ${j+1}">`).join('')).join('');$('vector').innerHTML=s.b.map((v,i)=>`<input type="number" step="any" value="${v}" aria-label="b ${i+1}">`).join('');$('initial').innerHTML=s.b.map((v,i)=>`<input type="number" step="any" value="0" aria-label="x inicial ${i+1}">`).join('');calculate();}
function inputValues(id){return [...$(id).querySelectorAll('input')].map(e=>e.value.trim()===''?NaN:Number(e.value));}
function chart(a,b,tol){let all=[...a,...b].map(h=>Math.log10(Math.max(h.res,1e-17))),lo=Math.min(-7,Math.floor(Math.min(...all)),Math.floor(Math.log10(tol))-1),hi=Math.max(0,Math.ceil(Math.max(...all))),n=Math.max(a.length,b.length)-1||1,X=k=>55+490*k/n,Y=v=>25+180*(hi-Math.log10(Math.max(v,1e-17)))/(hi-lo);let grid='';for(let e=hi;e>=lo;e-=Math.max(1,Math.ceil((hi-lo)/5)))grid+=`<line x1="55" y1="${Y(10**e)}" x2="545" y2="${Y(10**e)}" stroke="#e4eae7"/><text x="8" y="${Y(10**e)+4}">10^${e}</text>`;for(let k=0;k<=n;k++)grid+=`<text x="${X(k)-3}" y="229">${k}</text>`;return `<svg class="chart" viewBox="0 0 575 260" role="img" aria-label="Convergencia de GCP y GC: residuo en escala logarítmica por iteración">${grid}<line x1="55" x2="545" y1="${Y(tol)}" y2="${Y(tol)}" stroke="#a5b9b0" stroke-dasharray="5 4"/><text x="390" y="${Y(tol)-7}">Tolerancia ${tol.toExponential(0)}</text>${[[b,'#d29855'],[a,'#137568']].map(([hs,c])=>`<polyline points="${hs.map(h=>`${X(h.k)},${Y(h.res)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="2.5"/>`+hs.map(h=>`<circle cx="${X(h.k)}" cy="${Y(h.res)}" r="3" fill="${c}"/>`).join('')).join('')}<text x="260" y="254">Iteración k</text></svg>`;}
function calculate(){try{let a=inputValues('matrix'),A=Array.from({length:4},(_,i)=>a.slice(i*4,i*4+4)),b=inputValues('vector'),x0=inputValues('initial'),tol=Number($('tol').value),max=Number($('max').value),pre=$('pre').value==='jacobi',r=run(A,b,x0,tol,max,pre);last=r;$('error').hidden=true;let sum=r.ref.reduce((s,v)=>s+v,0),valid=r.ref.every(v=>v>=0)&&sum<=160,zero=b.every(v=>v===0);let modified=JSON.stringify(A)!==JSON.stringify(scenarios[current].A)||JSON.stringify(b)!==JSON.stringify(scenarios[current].b);let finite=Number.isFinite(r.condition)&&Number.isFinite(r.precondition);if(!finite)throw Error('Escala fuera del rango numérico; reduzca la magnitud de los coeficientes.');$('results').innerHTML=`<div class="stats"><div class="stat"><span class="small">PRESUPUESTO DE REFERENCIA</span><strong>${money(sum)}</strong><small>miles de Bs / trimestre</small></div><div class="stat"><span class="small">ITERACIONES GCP / GC</span><strong>${r.gcp.iterations} <span class="small">/ ${r.gc.iterations}</span></strong><small>${pre?'Jacobi':'Identidad'} · ${r.gcp.converged?'tolerancia alcanzada':'no convergió'}</small></div><div class="stat"><span class="small">κ∞(A)</span><strong>${fmt(r.condition)}</strong><small>Condición original</small></div><div class="stat"><span class="small">κ∞(M⁻¹A)</span><strong>${fmt(r.precondition)}</strong><small>Condición precondicionada</small></div></div><div class="twocol"><article class="panel"><h3>Convergencia del residuo</h3><div class="legend"><span>● GCP</span><span>● GC sin precondicionar</span></div>${chart(r.gcp.hist,r.gc.hist,tol)}<span class="small">${zero?'b = 0: residuo absoluto':'‖b − Ax‖₂ / ‖b‖₂'} · escala logarítmica; ceros en 10⁻¹⁷</span></article><article class="panel"><h3>Asignación de referencia por área</h3>${names.map((name,i)=>`<div class="budgetrow">${name}<b>${money(r.ref[i])} mil Bs</b><div class="moneybar"><i style="width:${Math.max(0,r.ref[i])/Math.max(...r.ref.map(Math.abs),1)*100}%"></i></div></div>`).join('')}<p class="${valid?'ok':'fail'}">${valid?'Dentro del fondo indicativo':'Requiere revisión de caja o no negatividad'} · saldo: ${money(160-sum)} mil Bs</p></article></div>${modified?'<p class="note">Datos personalizados: la solución corresponde a la matriz editada. Revalida el significado financiero de los coeficientes; las conclusiones de los escenarios originales no se transfieren automáticamente.</p>':''}${!r.gcp.converged?'<p class="note">GCP no alcanzó la tolerancia. Revisa Nmáx y la escala de los datos; no interpretes el vector como solución convergida.</p>':''}<h3>Soluciones y errores por componente</h3><div class="tablewrap">${table(['Área · miles de Bs','Referencia (Cholesky)','GCP','GC','Ea','Er','Ep (%)'],names.map((n,i)=>[n,fmt(r.ref[i]),fmt(r.gcp.x[i]),fmt(r.gc.x[i]),fmt(r.errors[i].ea),fmt(r.errors[i].er),fmt(r.errors[i].ep)]))}</div><p class="note">Residuo GCP: <b>${fmt(r.gcp.res)}</b> · GC: <b>${fmt(r.gc.res)}</b> (${r.gc.converged?'convergió':'no convergió'}). Comprueba los errores por componente antes de aprobar montos. El residuo global puede estar dominado por el componente de b con mayor escala.</p><details><summary>Sistema explícito, precondicionador y Cholesky</summary><div class="equation">${A.map((row,i)=>row.map((v,j)=>`(${fmt(v)})x${'₁₂₃₄'[j]}`).join(' + ')+' = '+fmt(b[i])).join('<br>')}</div><p>r₀ = ${vec(b.map((v,i)=>v-Nexo.mv(A,x0)[i]))}; M = diag(${vec(A.map((row,i)=>pre?row[i]:1))}).</p><p>Factor triangular L de A = LLᵀ:</p><pre class="matrixout">${matrixText(r.L)}</pre><p>Menores principales (Sylvester): ${vec(r.minors)}. Todos positivos.</p><p>Residuo de referencia: ${fmt(r.refres)}. Cálculo por Cholesky → Ly = b → Lᵀx = y.</p></details><details><summary>Bitácora GCP: α, β, aproximaciones y residuos</summary><div class="tablewrap">${table(['k','α usado','β para siguiente dirección','xₖ','Residuo verdadero'],r.gcp.hist.map(h=>[h.k,h.alpha===null?'—':fmt(h.alpha),h.beta===null?'—':fmt(h.beta),vec(h.x),fmt(h.res)]))}</div></details>`;}catch(e){last=null;$('results').innerHTML='';$('error').hidden=false;$('error').textContent=e.message;}}
function compare(){let rs=scenarios.map(s=>run(s.A,s.b));let rows=[['Referencia',...rs.map(r=>vec(r.ref))],['GCP',...rs.map(r=>vec(r.gcp.x))],['Ea por variable',...rs.map(r=>vec(r.errors.map(e=>e.ea)))],['Ep (%) por variable',...rs.map(r=>vec(r.errors.map(e=>e.ep)))],['Iteraciones GC',...rs.map(r=>r.gc.iterations)],['Iteraciones GCP',...rs.map(r=>r.gcp.iterations)],['κ∞(A)',...rs.map(r=>fmt(r.condition))],['κ∞(M⁻¹A)',...rs.map(r=>fmt(r.precondition))],['Residuo final GCP',...rs.map(r=>fmt(r.gcp.res))],['¿Convergió GCP?',...rs.map(r=>r.gcp.converged?'Sí':'No')],['Total (mil Bs)',...rs.map(r=>money(r.ref.reduce((a,b)=>a+b,0)))],['Interpretación',['Metas equilibradas; gasto cercano a la planificación inicial.'],['Menor disponibilidad reduce el total; la condición no cambia.'],['La rigidez contractual conserva soporte cerca de 25 y seguridad de 30. Jacobi compensa las escalas.']]];$('comparison').innerHTML=table(['Indicador',...scenarios.map(s=>s.name)],rows);$('proofs').innerHTML=rs.map((r,i)=>`<article class="panel"><h3>${scenarios[i].name} · verificación SPD</h3><p>A = Aᵀ; w = ${vec(scenarios[i].w)}, c = 0,5. La suma cuadrática es estrictamente positiva para v ≠ 0.</p><p>Menores principales: ${vec(r.minors)}.</p><p>b = ${vec(scenarios[i].b)}</p><pre class="matrixout">${matrixText(scenarios[i].A)}</pre></article>`).join('');}
function runQA(){let rows=qa(),input=$('vector').querySelector('input'),original=input.value,before=last?.ref[0];try{input.value=Number(original)+10;input.dispatchEvent(new Event('input',{bubbles:true}));let after=last?.ref[0];rows.push({name:'Edición en interfaz',input:'b₁ + 10 mediante evento input',expected:'DOM, referencia, GCP y errores actualizados',actual:before!==undefined&&after!==undefined?'x₁: '+fmt(before)+' → '+fmt(after):'Se requiere una entrada válida',ok:before!==undefined&&after!==undefined&&before!==after&&$('results').textContent.includes('Soluciones y errores')});}finally{input.value=original;input.dispatchEvent(new Event('input',{bubbles:true}));}let pass=rows.filter(r=>r.ok).length;$('qaout').innerHTML=`<p style="padding:0 16px" class="${pass===rows.length?'ok':'fail'}">${pass} / ${rows.length} pruebas aprobadas · Ejecutadas: ${new Date().toLocaleString('es-BO')}</p>`+table(['Prueba','Entrada','Resultado esperado','Resultado obtenido','Conclusión'],rows.map(r=>[r.name,r.input,r.expected,r.actual,`<span class="${r.ok?'ok':'fail'}">${r.ok?'Aprobada':'Revisar'}</span>`]));}
$('scenarioButtons').addEventListener('click',e=>{let b=e.target.closest('button');if(b)load(Number(b.dataset.scenario));});$('laboratorio').addEventListener('input',e=>{let t=e.target;if(t.id==='mirror')return;if(t.dataset.i!==undefined&&$('mirror').checked){let twin=$('matrix').querySelector(`[data-i="${t.dataset.j}"][data-j="${t.dataset.i}"]`);twin.value=t.value;}calculate();});$('pre').addEventListener('change',calculate);$('execute').onclick=calculate;$('reset').onclick=()=>{$('tol').value='0.000001';$('max').value='100';$('pre').value='jacobi';load(current);};$('runqa').onclick=runQA;
try{$('student').value=localStorage.getItem('nexo-student')||'';$('student').oninput=()=>localStorage.setItem('nexo-student',$('student').value);}catch(e){}
load(0);compare();runQA();const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}),{rootMargin:'-10% 0px -70% 0px'});document.querySelectorAll('main section').forEach(s=>observer.observe(s));
